async function openEpg(item){if(!item||item.kind!=='live'){status(T('حدد قناة مباشرة أولًا، ثم افتح EPG.','Focus a live channel first, then open EPG.'));return;}epgOrigin=document.activeElement;epgItem=item;const gen=++epgGeneration;$('epg-panel').hidden=false;$('epg-title').textContent='EPG · '+item.name;$('epg-list').textContent='';$('epg-status').textContent=T('جاري تحميل مواعيد البرامج من المزوّد…','Loading your provider’s programme guide…');$('epg-play').textContent=T('شاهد القناة','Watch channel');$('epg-close').textContent=T('رجوع','Back');$('epg-close').focus();try{let result=await call('epg',{id:item.id});if(gen!==epgGeneration)return;const rows=result.items||[];rows.forEach(row=>{const line=document.createElement('article'),time=document.createElement('time'),title=document.createElement('h3'),description=document.createElement('p');const start=new Date(Number(row.start)*1000),end=new Date(Number(row.end)*1000);time.textContent=start.toLocaleString()+' — '+end.toLocaleTimeString();title.textContent=row.title;description.textContent=row.description||'';line.tabIndex=0;line.className=Date.now()>=start.getTime()&&Date.now()<end.getTime()?'epg-now':'';line.append(time,title,description);$('epg-list').appendChild(line);});$('epg-status').textContent=rows.length?T('التوقيت حسب ساعة التلفزيون · المواعيد من المزوّد','TV local time · schedules supplied by your provider'):T('المزوّد لم يوفّر مواعيد برامج لهذه القناة.','Your provider has no programme guide for this channel.');}catch(e){if(gen===epgGeneration)$('epg-status').textContent=T('تعذّر تحميل دليل البرامج. جرّب تاني.','Programme guide could not load. Please retry.');}}
