function move(code){const startup=document.getElementById('iptv-startup-refresh');if(!startup&&window.TvIptvLayout&&TvIptvLayout.move(code))return;if(!startup&&dashboardMove(code,document.activeElement))return;const scope=startup||(!$('epg-panel').hidden?$('epg-panel'):!$('details-panel').hidden?$('details-panel'):$('settings-panel').hidden?document:$('settings-panel'));let all=Array.from(scope.querySelectorAll('button,input,select,[tabindex="0"]')).filter(e=>e.offsetWidth&&!e.disabled&&!e.closest('[hidden]')),current=document.activeElement;if(!all.includes(current)){if(startup){all[0]?.focus();return;}if(!$('dashboard').hidden)restorePortal();else (scope.querySelector('.tile')||all[0])?.focus();return;}let a=current.getBoundingClientRect(),ax=a.x+a.width/2,ay=a.y+a.height/2,best=null,score=Infinity;all.forEach(e=>{if(e===current)return;let b=e.getBoundingClientRect(),dx=b.x+b.width/2-ax,dy=b.y+b.height/2-ay;if(code===37&&dx>=-2||code===39&&dx<=2||code===38&&dy>=-2||code===40&&dy<=2)return;let horizontal=code===37||code===39,cost=Math.abs(horizontal?dx:dy)+Math.abs(horizontal?dy:dx)*3;if(cost<score){score=cost;best=e;}});if(best){best.focus();best.scrollIntoView({block:'nearest',inline:'nearest'});}}
document.addEventListener('keydown',e=>{if(e.defaultPrevented)return;if([27,10009,461].includes(e.keyCode)){e.preventDefault();back();}else if(e.keyCode>=37&&e.keyCode<=40){if(['SELECT','TEXTAREA'].includes(document.activeElement.tagName)||document.activeElement.isContentEditable)return;if(document.activeElement.tagName==='INPUT'&&(e.keyCode===37||e.keyCode===39))return;e.preventDefault();move(e.keyCode);}else if(e.keyCode===13&&document.activeElement.tagName==='BUTTON'){e.preventDefault();let target=document.activeElement;if(target.classList.contains('tile')){if(!held){held={target,long:false,timer:setTimeout(()=>{if(held){held.long=true;toggle(target._item);}},650)};}}else if(!e.repeat)target.click();}});
