async function changeEpisode(delta,id){if(episodeSwitchBusy)return {sent:false,message:episodeMessage('busy')};const current=lastPlayed&&lastPlayed.kind==='episode'&&String(lastPlayed.id)===String(id)?lastPlayed:null,sid=current&&String(current.category||'');if(!sid||!/^\d{1,14}$/.test(sid))return {sent:false,message:episodeMessage('missing')};episodeSwitchBusy=true;try{let page=0,previous=null,next=null;while(page<1000){const result=await call('list',{kind:'episode',category:sid,page,search:''}),rows=result.items||[],index=rows.findIndex(e=>String(e.id)===String(id));if(index>=0){if(delta<0)next=index>0?rows[index-1]:previous;else if(index+1<rows.length)next=rows[index+1];else if(result.hasMore){const following=await call('list',{kind:'episode',category:sid,page:page+1,search:''});next=(following.items||[])[0];}break;}if(!result.hasMore||!rows.length)break;previous=rows[rows.length-1];page++;}if(!next)return {sent:false,message:episodeMessage(delta<0?'first':'last')};const target=Object.assign({},next,{category:sid,seriesName:current.seriesName||'',icon:next.icon||current.icon,startOver:false});lastFocus=key(target);await call('play',target);return {sent:true};}catch(e){return {sent:false,message:e.message};}finally{episodeSwitchBusy=false;}}
